const fetch = require('node-fetch');
const Adzerk = require('@adzerk/management-sdk');
const apiKey = process.env.ADZERK_API_KEY;

async function uploadCreativeImage() {
  let specifications = await Adzerk.fetchSpecifications();
  let client = await Adzerk.buildClient({apiKey, specifications});

  // Style 1: Specify a file path
  let creative = await client.run('creative', "uploadImage", {
    id: 12345,
    image: "./adzerk-logo.png",
    sizeOverride: true,
  });

  console.log(creative);

  // Style 2: Specify an image from memory
  let response = await fetch('https://octodex.github.com/images/Fintechtocat.png');
  let buffer = response.buffer();

  let creative = await client.run('creative', 'uploadImage', {
    id: 12345,
    image: buffer,
    sizeOverride: true,
  });

  console.log(creative);

  // Style 3: Upload an image into a creative template field
  let creative = await client.run('creative', 'uploadImage', {
    id: 12345,
    image: "./adzerk-logo.png",
    fieldName: 'ctBannerImage',
  });

  console.log(creative);
}

uploadCreativeImage();

